void calculate_next(in vec3 pos, out vec3 nextPos, out float stepMetric) {
  float x = pos.x;
  float y = pos.y;
  float z = pos.z;
  float x_next = (x + 1.0);
  float nx = x_next;
  float y_next = ((nx + x_next) + y);
  float ny = y_next;
  float z_next = ((((nx + ny) + x_next) + y_next) + z);
  float nz = z_next;
  nextPos = vec3(nx, ny, nz);
  stepMetric = length(nextPos - pos);
}
